def blocks_1d(n, lines):
    out=[]; start=0
    for L in lines+ [n]:
        if L>start: out.append((start,L-1))
        start=L+1
    return out

def transform(grid):
    g=[list(r) for r in grid]; H,W=len(g),len(g[0])
    rws=[r for r in range(H) if len(set(g[r]))==1]
    cls=[c for c in range(W) if len({g[r][c] for r in range(H)})==1]
    sep=g[rws[0]][0]
    rb=blocks_1d(H,rws); cb=blocks_1d(W,cls)
    colors={g[r][c] for r in range(H) for c in range(W)} - {0,sep}
    def LR(m): return [row[::-1] for row in m]
    def TB(m): return m[::-1]
    def R180(m): return [row[::-1] for row in m[::-1]]
    inv={'TL':lambda m:m,'TR':LR,'BL':TB,'BR':R180}
    var =inv
    # anchor within design: (valign,halign) of sprite in design box
    anch={'TL':('b','r'),'TR':('b','l'),'BL':('t','r'),'BR':('t','l')}
    for c in colors:
        # cells containing color c
        cellset=set()
        for ri,(r0,r1) in enumerate(rb):
            for ci,(c0,c1) in enumerate(cb):
                if any(g[r][cc]==c for r in range(r0,r1+1) for cc in range(c0,c1+1)):
                    cellset.add((ri,ci))
        if not cellset: continue
        ris={ri for ri,ci in cellset}; cis={ci for ri,ci in cellset}
        if len(ris)!=2 or len(cis)!=2: continue
        r0i,r1i=sorted(ris); c0i,c1i=sorted(cis)
        posmap={(r0i,c0i):'TL',(r0i,c1i):'TR',(r1i,c0i):'BL',(r1i,c1i):'BR'}
        empty=[p for p in posmap if p not in cellset]
        if len(empty)!=1: continue
        ep=empty[0]; epos=posmap[ep]
        # sprite masks
        sprites={}
        for p in cellset:
            pos=posmap[p]; (r0,r1)=rb[p[0]]; (c0,c1)=cb[p[1]]
            m=[[1 if g[r][cc]==c else 0 for cc in range(c0,c1+1)] for r in range(r0,r1+1)]
            rs=[i for i,row in enumerate(m) if any(row)]; cs=[j for j in range(m[0].__len__()) if any(row[i][j] for i in range(len(m)))]
            sp=[[m[i][j] for j in range(min(cs),max(cs)+1)] for i in range(min(rs),max(rs)+1)]
            sprites[pos]=sp
        ch=rb[r1i][1]-rb[r0i][0]+1; cw=cb[c1i][1]-cb[c0i][0]+1
        mh=max(len(s) for s in sprites.values()); mw=max(len(s[0]) for s in sprites.values())
        best=None
        for h in range(mh,ch+1):
            for w in range(mw,cw+1):
                design=[[0]*w for _ in range(h)]; ok=True
                for pos,sp in sprites.items():
                    M=inv[pos](sp); sh,sw=len(M),len(M[0])
                    va,ha=anch[pos]
                    rs = h-sh if va=='b' else 0
                    cs = w-sw if ha=='r' else 0
                    for i in range(sh):
                        for j in range(sw):
                            if M[i][j]:
                                if design[rs+i][cs+j]==2: ok=False;break
                                design[rs+i][cs+j]=2
                        if not ok: break
                    if not ok: break
                if ok:
                    area=sum(r.count(2) for r in design)
                    key=(area,h,w)
                    if best is None or key<best[0]: best=(key,[row[:] for row in design])
        if best is None: continue
        design=best[1]; h=len(design); w=len(design[0])
        # complete empty outer rows/cols by duplicating adjacent filled row/col
        def complete(mat):
            mat=[row[:] for row in mat]
            changed=True
            while changed:
                changed=False
                hh=len(mat); ww=len(mat[0])
                filled=[i for i in range(hh) if any(mat[i])]
                if filled:
                    lo,hi=min(filled),max(filled)
                    if lo>0 and not any(mat[lo-1]): mat[lo-1]=mat[lo][:]; changed=True
                    if hi<hh-1 and not any(mat[hi+1]): mat[hi+1]=mat[hi][:]; changed=True
                filledc=[j for j in range(ww) if any(mat[i][j] for i in range(hh))]
                if filledc:
                    lo,hi=min(filledc),max(filledc)
                    if lo>0 and not any(mat[i][lo-1] for i in range(hh)):
                        for i in range(hh): mat[i][lo-1]=mat[i][lo]
                        changed=True
                    if hi<ww-1 and not any(mat[i][hi+1] for i in range(hh)):
                        for i in range(hh): mat[i][hi+1]=mat[i][hi]
                        changed=True
            return mat
        design=complete(design); h=len(design); w=len(design[0])
        # fill the empty cell
        (r0,r1)=rb[ep[0]]; (c0,c1)=cb[ep[1]]
        F=var[epos](design)
        va,ha=anch[epos]
        rs = (r1-r0+1)-h if va=='b' else 0
        cs = (c1-c0+1)-w if ha=='r' else 0
        for i in range(h):
            for j in range(w):
                if F[i][j]: g[r0+rs+i][c0+cs+j]=c
    return g

