def blocks_1d(n, lines):
    out=[]; start=0
    for L in list(lines)+[n]:
        if L>start: out.append((start,L-1))
        start=L+1
    return out

def cell_content(g,r0,r1,c0,c1,c):
    return [[1 if g[r][cc]==c else 0 for cc in range(c0,c1+1)] for r in range(r0,r1+1)]

def LRm(m): return [row[::-1] for row in m]
def TBm(m): return m[::-1]
def R180m(m): return [row[::-1] for row in m[::-1]]
VAR={'TL':lambda m:m,'TR':LRm,'BL':TBm,'BR':R180m}

def transform(grid):
    g=[list(r) for r in grid]; H,W=len(g),len(g[0])
    rws=[r for r in range(H) if len(set(g[r]))==1]
    cls=[cc for cc in range(W) if len({g[r][cc] for r in range(H)})==1]
    sep=g[rws[0]][0]
    rb=blocks_1d(H,rws); cb=blocks_1d(W,cls)
    colors={g[r][cc] for r in range(H) for cc in range(W)}-{0,sep}
    for c in colors:
        cells={}
        for ri,(r0,r1) in enumerate(rb):
            for ci,(c0,c1) in enumerate(cb):
                cont=cell_content(g,r0,r1,c0,c1,c)
                if any(any(row) for row in cont): cells[(ri,ci)]=cont
        if not cells: continue
        ris={ri for ri,ci in cells}; cis={ci for ri,ci in cells}
        if len(ris)!=2 or len(cis)!=2: continue
        r0i,r1i=sorted(ris); c0i,c1i=sorted(cis)
        posmap={(r0i,c0i):'TL',(r0i,c1i):'TR',(r1i,c0i):'BL',(r1i,c1i):'BR'}
        empt=[p for p in posmap if p not in cells]
        if len(empt)!=1: continue
        q=empt[0]; qpos=posmap[q]
        if 'TL' not in [posmap[p] for p in cells]: continue
        tl=[p for p in cells if posmap[p]=='TL'][0]
        C=cells[tl]
        ch=len(C); cw=len(C[0])
        # verify other present cells equal their cell-frame variants of C
        consist=all(cells[p]==VAR[posmap[p]](C) for p in cells if p!=tl)
        X=[row[:] for row in C]
        if consist:
            # extend: if bbox spans full width, extend height; if spans full height, extend width
            rows_any=[i for i in range(ch) if any(X[i])]
            cols_any=[j for j in range(cw) if any(X[i][j] for i in range(ch))]
            if cols_any and min(cols_any)==0 and max(cols_any)==cw-1:
                lo,hi=min(rows_any),max(rows_any)
                if lo>0: X[lo-1]=X[lo][:]
                if hi<ch-1: X[hi+1]=X[hi][:]
            if rows_any and min(rows_any)==0 and max(rows_any)==ch-1:
                lo,hi=min(cols_any),max(cols_any)
                if lo>0:
                    for i in range(ch): X[i][lo-1]=X[i][lo]
                if hi<cw-1:
                    for i in range(ch): X[i][hi+1]=X[i][hi]
        F=VAR[qpos](X)
        (r0,r1)=rb[q[0]]; (c0,c1)=cb[q[1]]
        for i in range(len(F)):
            for j in range(len(F[0])):
                if F[i][j]: g[r0+i][c0+j]=c
    return g

